// Module-level timer tracking for lab cleanup
const activeLabIntervals = [];
const activeLabTimeouts = [];
const activeLabFrames = [];

const setInterval = (fn, delay, ...args) => {
    const id = window.setInterval(fn, delay, ...args);
    activeLabIntervals.push(id);
    return id;
};

const setTimeout = (fn, delay, ...args) => {
    const id = window.setTimeout(fn, delay, ...args);
    activeLabTimeouts.push(id);
    return id;
};

const requestAnimationFrame = (fn) => {
    const id = window.requestAnimationFrame(fn);
    activeLabFrames.push(id);
    return id;
};

const clearAllLabTimers = () => {
    activeLabIntervals.forEach(window.clearInterval);
    activeLabIntervals.length = 0;
    activeLabTimeouts.forEach(window.clearTimeout);
    activeLabTimeouts.length = 0;
    activeLabFrames.forEach(window.cancelAnimationFrame);
    activeLabFrames.length = 0;
};
window.clearAllLabTimers = clearAllLabTimers;

window.showToast = (message, type = 'success') => {
    let container = document.getElementById('toast-container');
    if (!container) {
        container = document.createElement('div');
        container.id = 'toast-container';
        document.body.appendChild(container);
    }
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    const icon = type === 'success' ? '✅' : type === 'error' ? '❌' : '⚠️';
    toast.innerHTML = `
        <div class="toast-icon">${icon}</div>
        <div class="toast-message">${message}</div>
        <div class="toast-progress"></div>
    `;
    container.appendChild(toast);
    setTimeout(() => {
        toast.style.animation = 'slideOutToast 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards';
        setTimeout(() => toast.remove(), 400);
    }, 3000);
};

window.animateValue = (obj, start, end, duration, suffix = '') => {
    let startTimestamp = null;
    const step = (timestamp) => {
        if (!startTimestamp) startTimestamp = timestamp;
        const progress = Math.min((timestamp - startTimestamp) / duration, 1);
        obj.innerHTML = Math.floor(progress * (end - start) + start) + suffix;
        if (progress < 1) {
            window.requestAnimationFrame(step);
        }
    };
    window.requestAnimationFrame(step);
};

const getCurrentUser = () => {
    return new Promise((resolve, reject) => {
        const unsubscribe = onAuthStateChanged(auth, (user) => {
            unsubscribe();
            resolve(user);
        }, reject);
    });
};

const getStateKey = (labId) => {
    const data = window.VLAB_DATA ? window.VLAB_DATA[labId] : null;
    if (data && data.isMultiModule) {
        let modIdx = window.currentModuleIndex;
        if (modIdx === undefined || modIdx === null) {
            const modSelect = document.getElementById('moduleSelect');
            if (modSelect && modSelect.style.display !== 'none' && modSelect.value !== '') {
                modIdx = parseInt(modSelect.value, 10);
            } else {
                const savedIdx = localStorage.getItem(`${labId}_active_module`);
                modIdx = savedIdx ? parseInt(savedIdx, 10) : 0;
            }
        }
        if (isNaN(modIdx)) {
            modIdx = 0;
        }
        return `${labId}_mod_${modIdx}`;
    }
    return labId;
};

const syncProgress = async (labId, data) => {
    const user = auth.currentUser || await getCurrentUser();
    if (!user || !labId) {
        console.warn("Sync failed: User or Lab ID missing");
        return;
    }
    try {
        const pathKey = getStateKey(labId);
        await setDoc(doc(db, "users", user.uid, "progress", pathKey), {
            ...data,
            lastUpdated: new Date().toISOString()
        }, { merge: true });
        console.log("Progress synced to cloud");
    } catch (e) { console.error("Cloud sync failed", e); }
};

const syncTopology = async (labId, topoData) => {
    const user = auth.currentUser || await getCurrentUser();
    if (!user || !labId) return;
    try {
        await setDoc(doc(db, "users", user.uid, "topologies", labId), {
            ...topoData,
            lastUpdated: new Date().toISOString()
        }, { merge: true });
        console.log("Topology synced to cloud");
    } catch (e) { console.error("Topology cloud sync failed", e); }
};

const fetchProgress = async () => {
    const user = auth.currentUser || await getCurrentUser();
    if (!user) {
        console.warn("Fetch failed: User not authenticated");
        return;
    }
    try {
        const progSnap = await getDocs(collection(db, "users", user.uid, "progress"));
        progSnap.forEach(docSnap => {
            localStorage.setItem(`vlab_state_${docSnap.id}`, JSON.stringify(docSnap.data()));
        });

        const topoSnap = await getDocs(collection(db, "users", user.uid, "topologies"));
        topoSnap.forEach(docSnap => {
            localStorage.setItem(`vlab_topology_${docSnap.id}`, JSON.stringify(docSnap.data()));
        });

        console.log("Progress and topologies restored from cloud");
    } catch (e) {
        console.error("Restore failed", e);
        if (e.code === 'permission-denied') {
            console.warn("Firestore Permission Denied: Ensure rules allow access to 'users/{uid}/progress' and 'topologies'.");
        }
    } finally {
        const splash = document.getElementById('splash-screen');
        if (splash) {
            splash.style.opacity = '0';
            window.setTimeout(() => splash.style.display = 'none', 800);
        }
    }
};

window.fetchProgress = fetchProgress;
window.syncProgress = syncProgress;

// Intercept Canvas fillStyle and strokeStyle to support CSS variables natively
const originalFillStyle = Object.getOwnPropertyDescriptor(CanvasRenderingContext2D.prototype, 'fillStyle');
Object.defineProperty(CanvasRenderingContext2D.prototype, 'fillStyle', {
    set: function (val) {
        if (typeof val === 'string' && val.startsWith('var(')) {
            const varName = val.substring(4, val.length - 1).trim();
            const resolved = getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
            originalFillStyle.set.call(this, resolved || '#64748b');
        } else {
            originalFillStyle.set.call(this, val);
        }
    },
    get: function () {
        return originalFillStyle.get.call(this);
    }
});

const originalStrokeStyle = Object.getOwnPropertyDescriptor(CanvasRenderingContext2D.prototype, 'strokeStyle');
Object.defineProperty(CanvasRenderingContext2D.prototype, 'strokeStyle', {
    set: function (val) {
        if (typeof val === 'string' && val.startsWith('var(')) {
            const varName = val.substring(4, val.length - 1).trim();
            const resolved = getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
            originalStrokeStyle.set.call(this, resolved || '#64748b');
        } else {
            originalStrokeStyle.set.call(this, val);
        }
    },
    get: function () {
        return originalStrokeStyle.get.call(this);
    }
});

// Polyfill for roundRect if not supported
if (!CanvasRenderingContext2D.prototype.roundRect) {
    CanvasRenderingContext2D.prototype.roundRect = function (x, y, w, h, r) {
        if (typeof r === 'number') r = { tl: r, tr: r, br: r, bl: r };
        else r = { tl: r.tl || 0, tr: r.tr || 0, br: r.br || 0, bl: r.bl || 0 };
        this.beginPath();
        this.moveTo(x + r.tl, y);
        this.lineTo(x + w - r.tr, y);
        this.quadraticCurveTo(x + w, y, x + w, y + r.tr);
        this.lineTo(x + w, y + h - r.br);
        this.quadraticCurveTo(x + w, y + h, x + w - r.br, y + h);
        this.lineTo(x + r.bl, y + h);
        this.quadraticCurveTo(x, y + h, x, y + h - r.bl);
        this.lineTo(x, y + r.tl);
        this.quadraticCurveTo(x, y, x + r.tl, y);
        this.closePath();
        return this;
    };
}



const generatePDFReport = async (labId) => {
    // Show Loading Overlay
    const loader = document.createElement('div');
    loader.style.cssText = "position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(15,23,42,0.9); z-index:10000; display:flex; flex-direction:column; align-items:center; justify-content:center; color:white; font-family:Outfit, sans-serif; backdrop-filter:blur(8px);";
    loader.innerHTML = `
        <div class="pulse" style="width:80px; height:80px; background:var(--primary); border-radius:50%; margin-bottom:20px; box-shadow: 0 0 40px var(--primary);"></div>
        <h2 style="margin:0; font-size:24px;">Generating Academic Report</h2>
        <p style="opacity:0.7; margin-top:10px;">Compiling results, logs and visualizations...</p>
        <div style="width:200px; height:4px; background:rgba(255,255,255,0.1); border-radius:2px; margin-top:20px; overflow:hidden;">
            <div id="report-progress" style="width:0%; height:100%; background:var(--primary); transition:width 0.3s;"></div>
        </div>
    `;
    document.body.appendChild(loader);
    const progress = loader.querySelector('#report-progress');

    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF();
    const name = localStorage.getItem('vlab_user_name') || 'Student User';
    const data = window.VLAB_DATA[labId] || { title: "Custom Experiment", aim: "N/A", theory: { intro: "", cards: [] }, procedure: [] };

    // Helper to capture DOM elements (High Reliability Version)
    const addElementToPDF = async (elementId, title, yPos) => {
        const element = document.getElementById(elementId);
        if (!element) return yPos;

        const section = element.closest('.content-section');
        const wasActive = section?.classList.contains('active');

        try {
            if (section && !wasActive) {
                section.style.display = 'flex';
                section.style.opacity = '0';
                await new Promise(r => setTimeout(r, 300));
            }

            // 1. Prioritize Direct Canvas Export for SimCanvas
            if (elementId === 'simCanvas') {
                const canvas = element.querySelector('canvas') || (element.tagName === 'CANVAS' ? element : null);
                if (canvas && canvas.width > 0 && canvas.height > 0) {
                    // Force a re-render to ensure current state is captured
                    if (window.currentSim) window.currentSim.drawPerformanceGraphs();

                    const tempCanvas = document.createElement('canvas');
                    tempCanvas.width = canvas.width;
                    tempCanvas.height = canvas.height;
                    const ctx = tempCanvas.getContext('2d');
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
                    ctx.drawImage(canvas, 0, 0);

                    // Dark mode to Light mode filter for PDF
                    const imgDataRaw = ctx.getImageData(0, 0, tempCanvas.width, tempCanvas.height);
                    const data = imgDataRaw.data;
                    for (let i = 0; i < data.length; i += 4) {
                        const r = data[i], g = data[i + 1], b = data[i + 2];
                        if (r < 60 && g < 60 && b < 65) {
                            // Convert dark backgrounds to white
                            data[i] = 255; data[i + 1] = 255; data[i + 2] = 255;
                        } else if (r > 200 && g > 200 && b > 200) {
                            // Convert white text to black
                            data[i] = 0; data[i + 1] = 0; data[i + 2] = 0;
                        } else if (r > 150 && g > 150 && b > 150 && Math.abs(r - g) < 15 && Math.abs(g - b) < 15) {
                            // Convert light grey text to dark grey
                            data[i] = 50; data[i + 1] = 50; data[i + 2] = 50;
                        }
                    }
                    ctx.putImageData(imgDataRaw, 0, 0);

                    const imgData = tempCanvas.toDataURL('image/jpeg', 0.9);
                    pdf.setFont("helvetica", "bold"); pdf.setFontSize(12);
                    pdf.text(title, 20, yPos);
                    pdf.addImage(imgData, 'JPEG', 20, yPos + 5, 170, 85);
                    if (section && !wasActive) section.style.display = 'none';
                    return yPos + 100;
                }
            }

            // 2. Fallback to html2canvas for complex DOM elements
            const canvas = await html2canvas(element, {
                scale: 1.5,
                useCORS: true,
                backgroundColor: '#ffffff'
            });

            const imgData = canvas.toDataURL('image/jpeg', 0.8);
            pdf.setFont("helvetica", "bold"); pdf.setFontSize(12);
            pdf.text(title, 20, yPos);
            pdf.addImage(imgData, 'JPEG', 20, yPos + 5, 170, 85);

            if (section && !wasActive) section.style.display = 'none';
            return yPos + 100;

        } catch (e) {
            console.error(`Report capture failed for ${elementId}:`, e);
            pdf.setFont("helvetica", "italic"); pdf.setFontSize(10);
            pdf.text(`[Image Capture Failed for ${title}]`, 20, yPos + 10);
            return yPos + 20;
        }
    };

    progress.style.width = "10%";

    // Header
    pdf.setFillColor(30, 58, 138);
    pdf.rect(0, 0, 210, 40, 'F');
    pdf.setTextColor(255, 255, 255);
    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(22);
    pdf.text("MIT ADT UNIVERSITY", 105, 20, { align: 'center' });
    pdf.setFontSize(14);
    pdf.text("VIRTUAL NETWORKING LABORATORY REPORT", 105, 30, { align: 'center' });

    pdf.setTextColor(0, 0, 0);
    pdf.setFontSize(11);
    pdf.text(`Student: ${name}`, 20, 55);
    pdf.text(`Lab: ${data.title}`, 20, 62);
    pdf.text(`Date: ${new Date().toLocaleDateString()}`, 20, 69);

    progress.style.width = "30%";

    // Section 1 & 2: Aim & Theory
    pdf.setFontSize(14); pdf.setFont("helvetica", "bold");
    pdf.text("1. AIM", 20, 85);
    pdf.setFont("helvetica", "normal"); pdf.setFontSize(11);
    pdf.text(pdf.splitTextToSize(data.aim, 170), 20, 93);

    let y = 115;
    pdf.setFont("helvetica", "bold"); pdf.setFontSize(14);
    pdf.text("2. THEORY", 20, y); y += 8;
    pdf.setFont("helvetica", "normal"); pdf.setFontSize(11);
    const theoryLines = pdf.splitTextToSize(data.theory.intro, 170);
    pdf.text(theoryLines, 20, y); y += (theoryLines.length * 6) + 5;

    // Section 3: Procedure
    if (y > 200) { pdf.addPage(); y = 30; }
    pdf.setFont("helvetica", "bold"); pdf.setFontSize(14);
    pdf.text("3. PROCEDURE", 20, y); y += 8;
    pdf.setFont("helvetica", "normal"); pdf.setFontSize(11);
    data.procedure.forEach((step, i) => {
        const stepLines = pdf.splitTextToSize(`${i + 1}. ${step}`, 165);
        pdf.text(stepLines, 25, y);
        y += (stepLines.length * 6) + 2;
        if (y > 270) { pdf.addPage(); y = 30; }
    });

    progress.style.width = "50%";

    // Section 4: Visualizations
    pdf.addPage();
    y = 30;
    pdf.setFont("helvetica", "bold"); pdf.setFontSize(14);
    pdf.text("4. EXPERIMENT VISUALIZATIONS", 20, y); y += 15;

    y = await addElementToPDF('simCanvas', "A. Protocol Animation State", y);
    if (y > 200) { pdf.addPage(); y = 30; }
    y = await addElementToPDF('topology-builder-ui', "B. Configured Network Topology", y);

    progress.style.width = "70%";

    // Section 5: Results Table
    pdf.addPage();
    y = 30;
    pdf.setFont("helvetica", "bold"); pdf.setFontSize(14);
    pdf.text("5. PERFORMANCE RESULTS", 20, y); y += 10;

    const stats = [
        ["Metric", "Value"],
        ["Packets Sent", document.getElementById('statSent')?.textContent || "0"],
        ["Packets Acknowledged", document.getElementById('statAck')?.textContent || "0"],
        ["Network Efficiency", document.getElementById('statEff')?.textContent || "0%"],
        ["Average Throughput", document.getElementById('statThroughput')?.textContent || "0 Bps"]
    ];

    pdf.autoTable({
        startY: y,
        head: [stats[0]],
        body: stats.slice(1),
        theme: 'striped',
        headStyles: { fillColor: [30, 58, 138] }
    });
    y = pdf.lastAutoTable.finalY + 20;

    // Section 6: Observation Log Table
    pdf.setFont("helvetica", "bold"); pdf.setFontSize(14);
    pdf.text("6. DYNAMIC OBSERVATION TABLE", 20, y); y += 8;

    const observationRows = [];
    const obsTable = document.getElementById('observationTableBody');
    if (obsTable) {
        Array.from(obsTable.querySelectorAll('tr')).forEach(tr => {
            const tds = tr.querySelectorAll('td');
            if (tds.length === 4) {
                observationRows.push([tds[0].textContent, tds[1].textContent, tds[2].textContent, tds[3].textContent]);
            }
        });
    }

    if (observationRows.length > 0) {
        pdf.autoTable({
            startY: y,
            head: [["No.", "Time", "Activity/Event Detail", "Status"]],
            body: observationRows.reverse().slice(-15),
            theme: 'grid',
            styles: { fontSize: 8 },
            headStyles: { fillColor: [16, 185, 129] }
        });
        y = pdf.lastAutoTable.finalY + 15;
    } else {
        pdf.setFont("helvetica", "italic"); pdf.setFontSize(10);
        pdf.text("No specific simulation events observed during this session.", 25, y);
        y += 15;
    }

    // Section 7: Command Execution History
    if (y > 230) { pdf.addPage(); y = 30; }
    pdf.setFont("helvetica", "bold"); pdf.setFontSize(14);
    pdf.text("7. COMMAND EXECUTION HISTORY", 20, y); y += 8;

    const typedCmds = window.vlabTypedCommands || [];
    if (typedCmds.length > 0) {
        const cmdRows = typedCmds.map(c => [c.timestamp, c.host, c.cmd]);
        pdf.autoTable({
            startY: y,
            head: [["Timestamp", "Device", "Command Typed"]],
            body: cmdRows,
            theme: 'striped',
            styles: { fontSize: 8 },
            headStyles: { fillColor: [59, 130, 246] }
        });
        y = pdf.lastAutoTable.finalY + 15;
    } else {
        pdf.setFont("helvetica", "italic"); pdf.setFontSize(10);
        pdf.text("No CLI commands executed during this session.", 25, y);
        y += 15;
    }

    // Section 8: Conclusion
    if (y > 240) { pdf.addPage(); y = 30; }
    pdf.setFont("helvetica", "bold"); pdf.setFontSize(14);
    pdf.text("8. CONCLUSION", 20, y); y += 10;
    pdf.setFont("helvetica", "normal"); pdf.setFontSize(11);
    const concl = "The experiment successfully demonstrated the requested protocol behaviors. Live simulation verified packet flow, efficiency metrics, and topological connectivity in accordance with academic requirements.";
    pdf.text(pdf.splitTextToSize(concl, 170), 20, y);

    progress.style.width = "100%";
    setTimeout(() => {
        pdf.save(`${data.title.replace(/ /g, '_')}_Academic_Report.pdf`);
        loader.remove();
    }, 500);
};

